// themes.js: the app's themes (GENERATED by tools/themes.py from tools/themes-template.js: edit those). A classic
// script in <head>, so the saved theme is on <html> before the first paint (no flash of the retro colours):
// data-skin (the token block in css/themes.css; none for Retro, the default), data-light, data-stars, data-font and
// data-radius (the shared looks). window.GGTheme: {list, get(), set(id), picker()}; set() fires 'gg:theme' on window.
// The picker: a full-screen chooser (Classic, Creative, NFL teams) opened from the title screen's "Change theme" and
// from the You sheet; a tap applies the theme at once.
(function () {
  var THEMES = /*THEMES*/[];
  var KEY = 'gg-skin', root = document.documentElement;
  var byId = function (id) { for (var i = 0; i < THEMES.length; i++) if (THEMES[i].id === id) return THEMES[i]; return null; };
  var attr = function (k, v) { if (v) root.setAttribute(k, v); else root.removeAttribute(k); };
  function meta(name, v) {
    var m = document.querySelector('meta[name="' + name + '"]');
    if (!m) { m = document.createElement('meta'); m.setAttribute('name', name); document.head.appendChild(m); }
    m.setAttribute('content', v);
  }
  function apply(id) {
    var t = byId(id) || THEMES[0], retro = t.id === 'retro';
    attr('data-skin', retro ? '' : t.id);
    attr('data-light', t.light ? '1' : '');
    attr('data-stars', retro ? '' : t.stars || '');
    attr('data-font', retro ? '' : t.font || 'modern');
    attr('data-radius', t.radius || '');
    meta('theme-color', t.bg);
    meta('color-scheme', t.light ? 'light' : 'dark');
    return t;
  }
  function get() { var id = null; try { id = localStorage.getItem(KEY); } catch (_) {} return byId(id) ? id : 'retro'; }
  function set(id) {
    var t = apply(id);
    try { localStorage.setItem(KEY, t.id); } catch (_) {}
    try { window.dispatchEvent(new CustomEvent('gg:theme', {detail: {id: t.id}})); } catch (_) {}
    return t;
  }
  apply(get());

  var esc = function (s) { return String(s).replace(/[&<>"]/g, function (c) { return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c]; }); };
  var LOGO = function (id) { return 'https://a.espncdn.com/combiner/i?img=/i/teamlogos/nfl/500/' + id + '.png&h=80&w=80'; };
  function tile(t, cur) {
    var s = t.sw;
    return '<button type="button" class="tp-t" role="radio" aria-checked="' + (t.id === cur) + '" data-skin-id="' + t.id + '">'
      + '<span class="tp-prev" style="background:' + s[0] + '" aria-hidden="true"><i class="p-card" style="background:' + s[1] + '"></i>'
      + '<i class="p-bar" style="background:' + s[2] + '"></i><i class="p-dot" style="background:' + s[3] + '"></i><i class="p-btn" style="background:' + s[2] + '"></i>'
      + (t.group === 'NFL' ? '<img src="' + LOGO(t.id) + '" alt="" loading="lazy" decoding="async" onerror="this.remove()">' : '')
      + '<span class="tp-check"><svg class="ic" aria-hidden="true"><use href="#i-check"/></svg></span></span>'
      + '<span class="tp-nm">' + esc(t.name) + '</span>' + (t.note ? '<span class="tp-note">' + esc(t.note) + '</span>' : '') + '</button>';
  }
  var open = null;
  function picker() {
    if (open) return open.p;
    var cur = get(), back = document.activeElement;
    var sec = function (label, g, cls) {
      var ts = THEMES.filter(function (t) { return t.group === g; });
      return '<p class="tp-sec">' + label + '</p><div class="tp-grid' + (cls ? ' ' + cls : '') + '" role="radiogroup" aria-label="' + label + '">' + ts.map(function (t) { return tile(t, cur); }).join('') + '</div>';
    };
    var el = document.createElement('div');
    el.id = 'theme-picker';
    el.setAttribute('role', 'dialog');
    el.setAttribute('aria-modal', 'true');
    el.setAttribute('aria-label', 'Choose a theme');
    el.innerHTML = '<div class="tp-head"><h2>Choose a theme</h2><button type="button" class="tp-done" data-tp-done>Done</button></div>'
      + '<div class="tp-body">' + sec('Classic', 'Classic') + sec('Creative', 'Creative') + sec('NFL teams', 'NFL', 'is-nfl') + '</div>';
    var done;
    var p = new Promise(function (r) { done = r; });
    var close = function () {
      document.removeEventListener('keydown', key, true);
      el.remove(); open = null;
      try { if (back && back.focus) back.focus({preventScroll: true}); } catch (_) {}
      done(get());
    };
    var key = function (e) { if (e.key === 'Escape') { e.preventDefault(); close(); } };
    el.addEventListener('click', function (e) {
      e.stopPropagation();
      if (e.target.closest('[data-tp-done]')) { close(); return; }
      var b = e.target.closest('[data-skin-id]');
      if (!b) return;
      set(b.getAttribute('data-skin-id'));
      el.querySelectorAll('[data-skin-id]').forEach(function (x) { x.setAttribute('aria-checked', String(x === b)); });
      try { if (navigator.vibrate) navigator.vibrate(8); } catch (_) {}
    });
    document.addEventListener('keydown', key, true);
    document.body.appendChild(el);
    var sel = el.querySelector('[aria-checked="true"]');
    try { (sel || el.querySelector('[data-tp-done]')).focus({preventScroll: true}); if (sel) sel.scrollIntoView({block: 'center'}); } catch (_) {}
    open = {p: p};
    return p;
  }
  window.GGTheme = {list: THEMES, get: get, set: set, picker: picker};
})();
